import random
import itertools
from collections import deque

def girth(graph, n):
    """Find the girth of the graph (shortest cycle length)."""
    min_cycle = float('inf')
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
        if min_cycle == 3:
            return 3
    return min_cycle if min_cycle != float('inf') else -1  # -1 means no cycle (acyclic)

def is_colorable(graph, n, k):
    """Check if graph is k-colorable using backtracking."""
    colors = [-1] * n

    def can_color(v, c):
        for u in graph[v]:
            if colors[u] == c:
                return False
        return True

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            if can_color(v, c):
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def random_graph_with_edges(n, m, seed=None):
    if seed is not None:
        random.seed(seed)
    all_edges = [(i, j) for i in range(n) for j in range(i+1, n)]
    edges = random.sample(all_edges, m)
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    return graph, edges

